import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 fuzzUnlockTime, uint128 fuzzValue, address actor) public {
        // Keep domains wide but sensible
        vm.assume(actor != address(0));
        // fuzzValue is amount of wei to send; bound to reasonable range so vm.deal works
        uint256 value = bound(uint256(fuzzValue), 0, 10 ether);

        // fund the actor so they can send value
        vm.deal(actor, value + 1 ether);

        // perform the Put call as the actor, sending value wei and passing fuzzUnlockTime
        vm.prank(actor);
        // wrap call in try/catch just in case (reference should accept the call)
        bool ok;
        try c.Put{value: value}(fuzzUnlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property (single assertion): if the Put call succeeded, then
        // the stored unlockTime for the actor is >= current block.timestamp.
        // This holds for the reference contract for all inputs, and the mutant that
        // assigns unlockTime = _unlockTime will fail this for some inputs where
        // fuzzUnlockTime < block.timestamp.
        if (ok) {
            // read the stored unlockTime via public mapping getter
            (uint256 storedUnlockTime, ) = c.Acc(actor);
            assertTrue(storedUnlockTime >= block.timestamp);
        } else {
            // If the call reverted, then nothing further to assert; keep test valid
            // by asserting that ok is false implies storedUnlockTime is unchanged (no access),
            // but per the test requirements we must have exactly one assertTrue reading c when possible.
            // Here, when call reverts, we simply assertTrue(true) would be invalid; instead, assert that ok==false
            // is not allowed as extra assertion. To satisfy the single-assert rule, we convert the fact
            // into an assertion that ok implies the property. Use implication via assertTrue(!ok || ...)
            // (However, because we already branched, keep a single assertTrue by combining)
        }
    }
}

