    function testFuzz_property(uint256 _unlockTime, address caller) public {
        // Keep caller in the wide admissible domain but avoid the zero address to be realistic
        if (caller == address(0)) caller = address(1);

        // fund the caller so they can send value
        uint256 sendVal = 1 ether; // MinSum is 1 ether in the contract
        vm.deal(caller, sendVal);

        // ensure we are at a deterministic time but let fuzzer choose _unlockTime freely
        // do not over-constrain _unlockTime; allow any uint256
