        // call Put with fuzzed _unlockTime and send 1 ether
        // capture whether the call succeeded (reference always succeeds)
        bool ok;
        try c.Put{value: sendVal}(_unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

