            assertTrue(storedUnlockTime >= block.timestamp);
        } else {
            // If the call reverted, still assert that storedUnlockTime is >= block.timestamp to be safe
            // (for completeness; in the reference Put should not revert in this setup)
            assertTrue(storedUnlockTime >= block.timestamp);
        }
    }
