contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: amount to send and an unlockTime candidate
    function testFuzz_property(uint256 amt, uint256 unlockTimeCandidate) public {
        // keep amt reasonable (not zero) and within balanceable range
        vm.assume(amt <= type(uint128).max); // keep gas/call sizes sane
        vm.assume(amt > 0);

        // fund the caller (this test contract) so it can send amt
        vm.deal(address(this), amt + 1 ether);

        // record current time
        uint256 tBefore = block.timestamp;

        // Call Put with the fuzzed unlockTimeCandidate and fuzzed amount
        // Use low-level try/catch to catch unexpected reverts; we only assert on stored unlockTime
        bool ok;
        try c.Put{value: amt}(unlockTimeCandidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees that after a successful Put call,
        // Acc[msg.sender].unlockTime >= block.timestamp (i.e., not set to a past time).
        // We assert that if the call succeeded, the stored unlockTime is >= tBefore (block.timestamp at call time)
        // This holds for the reference for ALL admissible inputs; the mutant can violate it for some inputs.
        if (ok) {
            // read the public getter for Acc mapping: Acc returns (unlockTime, balance) via autogenerated getter
            (uint256 storedUnlock, uint256 bal) = c.Acc(address(this));
            assertTrue(storedUnlock >= tBefore);
        } else {
            // if the call reverted, the invariant about stored state after a successful call is vacuously true
            assertTrue(true);
        }
    }
}

