pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: unlockTime (could be past/future) and a nonzero wei amount
    function testFuzz_property(uint256 _unlockTime, uint256 _amount) public {
        // keep amount within reasonable bounds and nonzero so Put actually receives value
        _amount = bound(_amount, 1, 10 ether);

        // We need an address to call from; use a fuzzed address but fund and prank it
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(_unlockTime, _amount, block.timestamp)))));
        vm.deal(actor, _amount);

        // We will target inputs where _unlockTime is strictly less than current block.timestamp
        // because the reference clamps to block.timestamp, while the mutant would store the raw past value.
        // Constrain admissible domain so the reference's guarantee applies: require _unlockTime < block.timestamp
        // but keep wide by allowing any uint that meets that relation.
        vm.assume(_unlockTime < block.timestamp);

        // perform the call as the actor, sending _amount wei
        vm.prank(actor);
        c.Put{value: _amount}(_unlockTime);

        // single assertion: after Put, the stored Acc[actor].unlockTime must be >= block.timestamp
        // This is the universal property the reference satisfies for all admissible inputs; the mutant that
        // sets unlockTime = _unlockTime (a past value) will violate it for some fuzzed inputs.
        (uint storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime >= block.timestamp);
    }
}

