contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: sender address and amount. The property: after Put, the increase in Acc[sender].balance equals the msg.value sent and the call succeeds.
    function testFuzz_property(address sender, uint256 amt) public {
        // keep domain reasonable: amount up to some large value but within uint256
        vm.assume(sender != address(0));
        uint256 amount = bound(amt, 0, 10 ether);

        // prepare funds for sender
        vm.deal(sender, amount);

        // record prior balance via public getter: Acc is public mapping, returns Holder (two uints).
        (uint256 priorUnlock, uint256 priorBal) = c.Acc(sender);

        bool ok;
        // perform the call as sender with value amount
        vm.prank(sender);
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // read after state
        (uint256 afterUnlock, uint256 afterBal) = c.Acc(sender);

        // General rule: on the correct contract, Put always succeeds and the balance increases exactly by msg.value
        // i.e., ok == true AND afterBal == priorBal + amount
        assertTrue(ok && afterBal == priorBal + amount);
