pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor address and amount to send
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep domain wide but meaningful: amount should be within reasonable range
        // and actor cannot be address(0) to avoid odd autostring behavior in logs
        vm.assume(actor != address(0));
        // bound amount to < 2**255 to avoid trivial overflow attempts via extremely large values,
        // but still allow large values so the fuzzer can discover edge cases
        amount = bound(amount, 0, type(uint256).max / 4);

        // snapshot pre-balance stored in contract getter
        uint256 pre = c.Acc(actor).balance;

        // fund the actor so they can send `amount` value
        vm.deal(actor, amount);
        bool ok;
        // perform the payable call from actor, capturing whether it reverted
        vm.prank(actor);
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call: for the reference C, Put never reverts and increases balance by exactly msg.value
        // So assert that the call succeeded and post.balance == pre + amount
        uint256 post = c.Acc(actor).balance;
        assertTrue(ok && post == pre + amount);
    }
}
